let html5QrCode;const qrReaderDiv=document.getElementById("qr-reader");const scanner_barcode_form=document.forms.scanner_barcode_form;executeFunc((function initHtml5Qrcode(){if(typeof Html5Qrcode!=="function"){return false}try{const stream=navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"}});html5QrCode=new Html5Qrcode("qr-reader",{fps:10,qrbox:(viewfinderWidth,viewfinderHeight)=>{const minEdge=Math.min(viewfinderWidth,viewfinderHeight);return{width:minEdge*.8,height:minEdge*.8}},rememberLastUsedCamera:true,supportedScanTypes:[Html5QrcodeScanType.SCAN_TYPE_CAMERA],showTorchButtonIfSupported:true,showZoomSliderIfSupported:true,defaultZoomValueIfSupported:1});qrReaderDiv.style.display="block";const config={fps:20,qrbox:{width:250,height:250}};html5QrCode.start({facingMode:"environment"},config,onScanSuccess)}catch(err){console.error(err)}return true}));async function onScanSuccess(decodedText,decodedResult){await html5QrCode.stop();qrReaderDiv.style.display="none";await sendCodeToServer(decodedText)}async function sendCodeToServer(qrText){let modal=document.getElementById("modal");modal.innerHTML='<div class="modal-dialog modal-dialog-centered modal-xl">\n'+'        <div class="modal-content border-0 bg-transparent shadow-none">\n'+'            <div class="d-flex justify-content-center w-100">\n'+'                <button type="button" class="btn btn-link w-100" style="min-height: 500px;" data-bs-dismiss="modal">\n'+'                    <div class="spinner-border text-light" role="status">\n'+'                        <span class="visually-hidden">Loading...</span>\n'+"                    </div>\n"+"                </button>\n"+"            </div>\n"+"        </div>\n"+"    </div>";bootstrap.Modal.getOrCreateInstance(modal).show();try{const data=new FormData(scanner_barcode_form);data.set(scanner_barcode_form.name+"[code]",qrText);const response=await fetch(scanner_barcode_form.action,{method:scanner_barcode_form.method,cache:"no-cache",credentials:"same-origin",headers:{"X-Requested-With":"XMLHttpRequest"},redirect:"follow",referrerPolicy:"no-referrer",body:data}).then((response=>{if(response.status===302){window.location.reload()}if(response.status!==200){return false}return response.text()})).then((data=>{modal.innerHTML=data;modal.addEventListener("hidden.bs.modal",(function(event){location.reload()}));modal.querySelectorAll("form").forEach((function(forms){forms.addEventListener("submit",(function(event){event.preventDefault();submitModalForm(forms);return false}))}));let lazy=document.createElement("script");lazy.src="/assets/"+$version+"/js/lazyload.min.js?v="+Date.now()}))}catch(error){console.error("Ошибка отправки:",error)}}